};
scwin.fn_read_sync = async function() {
    //dma_Item.set("bzProcsNo", scwin.vBzProcsNo);

    let reqMap = {
        bzProcsNo: scwin.vBzProcsNo
    };

    const sbmOptions = {
        id: "sbm_bzprocsno_select-one",
        action: "/api/listing/lstproc/stock/issuance-manage-kindstk-detail/select-one",
        method: "get",
        target: "dma_Item=body",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

    // if (dma_Item.get(1, "BZ_PROCS_NO") == '') {
    //     buttonSet.setInsertStatus();
    //     dma_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIND_STK_DTL_INOUT";
    //     dma_Item.reset();
    //     dma_Item.insertRow();
    // } else {
    //     buttonSet.setUpdateStatus();
    // }

    if(dma_Item.get("bzProcsNo") == "") {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);

         let reqMap2 = {
            bzProcsNo: scwin.vPRELM_INVSTG_BZ_PROCS_NO
        };
        const sbmOptions2 = {
            id: "sbm_bzprocsno_select-one2",
            action: "/api/listing/lstproc/stock/issuance-manage-kindstk-detail/select-one",
            method: "get",
            target: "dma_Item=body",
            isProcessMsg: false
        };
        const res2 = await $c.sbm.executeDynamic(sbmOptions2, reqMap2);

        if(dma_Item.get("bzProcsNo") != '') {
            dma_Item.set("bzProcsNo", "");
        } else {
            dma_Item.reset();
        }
    } else {
        $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
    }





};
scwin.initForm = function() {

    if (dma_Item.get("acctpYn") == '') dma_Item.set("acctpYn", 0);
    if (dma_Item.get("cashDivYn") == '') dma_Item.set("cashDivYn",0);
    if (dma_Item.get("cmstkPct1DivYn") == '') dma_Item.set("cmstkPct1DivYn",0);
    if (dma_Item.get("comCashRedmptYn") == '') dma_Item.set("comCashRedmptYn",0);
    if (dma_Item.get("comConvRghtYn") == '') dma_Item.set("comConvRghtYn",0);
    if (dma_Item.get("comRedmptRghtYn") == '') dma_Item.set("comRedmptRghtYn",0);
    if (dma_Item.get("convYn") == '') dma_Item.set("convYn",0);       
    if (dma_Item.get("lwstDivRtDscYn") == '') dma_Item.set("lwstDivRtDscYn",0);       
    if (dma_Item.get("miscDivYn") == '') dma_Item.set("miscDivYn",0);       
    if (dma_Item.get("ndivtmVoterghtYn") == '') dma_Item.set("ndivtmVoterghtYn",0);       
    if (dma_Item.get("partctpYn") == '') dma_Item.set("partctpYn",0);       
    if (dma_Item.get("proftDivRemk") == '') dma_Item.set("proftDivRemk",0);       
    if (dma_Item.get("proftDivYn") == '') dma_Item.set("proftDivYn",0);       
    if (dma_Item.get("redmptYn") == '')  dma_Item.set("redmptYn",0);       
    if (dma_Item.get("remainProprtDistrYn") == '') dma_Item.set("remainProprtDistrYn",0);       
    if (dma_Item.get("shrhdCashRedmptYn") == '') dma_Item.set("shrhdCashRedmptYn",0);       
    if (dma_Item.get("shrhdConvRghtYn") == '') dma_Item.set("shrhdConvRghtYn",0);       
    if (dma_Item.get("shrhdRedmptRghtYn") == '') dma_Item.set("shrhdRedmptRghtYn",0);       
    if (dma_Item.get("voterghtExcldYn") == '') dma_Item.set("voterghtExcldYn",0);       
    if (dma_Item.get("voterghtLmtYn") == '') dma_Item.set("voterghtLmtYn",0);       
    if (dma_Item.get("proftDivYn") == "1") {
        //$c.stf.showObj(panel_1, true);
        panel_1.show();
    } else {
        //$c.stf.showObj(panel_1, false);
        panel_1.hide();
    }
    if (dma_Item.get("remainProprtDistrYn") == "Y") {
        //$c.stf.showObj(panel_2, true);
        panel_2.show();
    } else {
        //$c.stf.showObj(panel_2, false);
        panel_2.hide();
    }
    if (dma_Item.get("voterghtExcldYn") == "Y") {
        //$c.stf.showObj(panel_3, true);
        panel_3.show();
    } else {
        //$c.stf.showObj(panel_3, false);
        panel_3.hide();
    }
    if (dma_Item.get("voterghtLmtYn") == "Y") {
        //$c.stf.showObj(panel_4, true);
        panel_4.show();
    } else {
        //$c.stf.showObj(panel_4, false);
        panel_4.hide();
    }
    if (dma_Item.get("redmptYn") == "Y") {
        if (dma_Item.get("comRedmptRghtYn") == "Y") {
            panel_6.show();
        } else {
            //$c.stf.showObj(panel_6, false);
            panel_6.hide();
        }
        if (dma_Item.get("shrhdRedmptRghtYn") == "Y") {
            //$c.stf.showObj(panel_7, true);
            panel_7.show();
        } else {
            //$c.stf.showObj(panel_7, false);
            panel_7.hide();
        }
        panel_5.show();
        //$c.stf.showObj(panel_5, true);
    } else {
        //$c.stf.showObj(panel_6, false);
        //$c.stf.showObj(panel_7, false);
        //$c.stf.showObj(panel_5, false);
        panel_5.hide();
        panel_6.hide();
        panel_7.hide();
    }
    if (dma_Item.get("convYn") == "Y") {
        if (dma_Item.get("comConvRghtYn") == "Y") {
            //$c.stf.showObj(panel_9, true);
            panel_9.show();
        } else {
            //$c.stf.showObj(panel_9, false);
            panel_9.hide();
        }
        if (dma_Item.get("shrhdConvRghtYn") == "Y") {
            //$c.stf.showObj(panel_10, true);
            panel_10.show();
        } else {
            //$c.stf.showObj(panel_10, false);
            panel_10.hide();
        }
        //$c.stf.showObj(panel_8, true);
        panel_8.show();
    } else {
        //$c.stf.showObj(panel_9, false);
        //$c.stf.showObj(panel_10, false);
        //$c.stf.showObj(panel_8, false);
        panel_8.hide();
        panel_9.hide();
        panel_10.hide();
    }
}
scwin.fn_CheckForm = function() {
    //todo
    if (dma_Item.get("redmptYn") == 0) {
        if ($c.win.confirm("[상환]이 체크되지 않았기 때문에 하위 구성값은 제거됩니다.\n계속 하시겠습니까?")) {
            dma_Item.set("comRedmptRghtYn", 0);
            dma_Item.set("shrhdRedmptRghtYn", 0);
            dma_Item.set("comRedmptPdStrtDd", '');
            dma_Item.set("comCashRedmptYn", 0);
            dma_Item.set("comRedmptRemk", '');
            dma_Item.set("shrhdRedmptPdStrtDd", '');
            dma_Item.set("shrhdRedmptPdEndDd", '');
            dma_Item.set("shrhdCashRedmptYn", 0);
            dma_Item.set("shrhdRedmptRemk", '');
        } else {
            return false;
        }
    }
    if (dma_Item.get("convYn") == 0) {
        if ($c.win.confirm("[전환]이 체크되지 않았기 때문에 하위 구성값은 제거됩니다.\n계속 하시겠습니까?")) {
            dma_Item.set("comConvRghtYn", 0);
            dma_Item.set("comConvRto", 0);
            dma_Item.set("comConvObjStkContn", '');
            dma_Item.set("comConvRdStrtDd", '');
            dma_Item.set("comConvRdEndDd", '');
            dma_Item.set("comConvRemk", '');
            dma_Item.set("shrhdConvRghtYn", 0);
            dma_Item.set("shrhdConvRto", 0);
            dma_Item.set("shrhdConvObjStkContn", '');
            dma_Item.set("shrhdConvPdStrtDd", '');
            dma_Item.set("shrhdConvPdEndDd", '');
            dma_Item.set("shrhdConvRemk", '');
        } else {
            return false;
        }
    }
    return true;
};

scwin.fn_save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.fn_CheckForm()) {
        if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dma_Item.UserStatus(1) = TB_JOB_INSERT;*/
            //X = TB_JOB_INSERT;
            //alert("BZ_PROCS_NO>>>>>>>> :"+dma_Item.NameValue(1,"BZ_PROCS_NO"));
            dma_Item.set("bzProcsNo", scwin.vBzProcsNo);

            scwin.fn_trs();
        }
    }
};
scwin.fn_update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!await $c.lc.isProcess(scwin.TR_JOB)) return; 
        /*ORG SRC: dma_Item.UserStatus(1) = TB_JOB_UPDATE;*/ 
        //X = TB_JOB_UPDATE;
        scwin.fn_trs();
    }
};
scwin.fn_trs = async function() {
    var vScrenProcTpCd;
    var actionUrl = "";
    if (scwin.TR_JOB == "I") {
        //vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
        actionUrl = "/api/listing/lstproc/kind/listing-review/kind-stk/register";
    } else if (scwin.TR_JOB == "U") {
        //vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        actionUrl = "/api/listing/lstproc/kind/listing-review/kind-stk/modify";
    }
    dma_Item.set("bzProcsNo", scwin.vBzProcsNo);

    const sbmOptions = {
        id: "sbm_kindStk",
        action: actionUrl,
        method: "post",
        ref: "dma_Item",
        //target: "dlt_listMaintradeBank=body",
        // submitDoneHandler: scwin.sbm_listCodeValue_submitdone,
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);

    scwin.trs_Save_OnSuccess();

    //trs_Save.Action = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveKindStkDtl";
    //trs_Save.KeyName = "toinb_dataid4";
    //trs_Save.KeyValue = "JSP(I:pInput=dma_Item)";
    //trs_Save.Post();
};
// scwin.dma_Item_OnLoadError = function() {
//     $c.stf.alert_error(dma_Item);
// };
// scwin.dma_Item_OnLoadCompleted = function() {

// };
scwin.trs_Save_OnSuccess = function() {
    //$c.lc.alertMsg('S');
    if(scwin.TR_JOB == "I") {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    }
    scwin.fn_read_sync();
    /* if (buttonSet.status == "U") {
        var parentWin = $c.win.getParent();
    } */
};
