scwin.init = async function() {
    //$c.libRoundPanel.PanelToGroupBox(panel_Item);
    //var parentWin = $c.win.getParent();
    scwin.vBzProcsNo = $c.win.getParent().scwin.vBzProcsNo;
    scwin.vListProcsStatCd = $c.win.getParent().scwin.vListProcsStatCd;
    scwin.vPRELM_INVSTG_BZ_PROCS_NO = $c.win.getParent().scwin.vPRELM_INVSTG_BZ_PROCS_NO;
    scwin.mktTpCd = $c.win.getParent().scwin.mktTpCd;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    //buttonSet.setSaveInfo( btn_Save, fn_save ); 		// 저장
    //buttonSet.setUpdateInfo( btn_Update, fn_update ); 	// 수정

    //alert("vBzProcsNo :"+vBzProcsNo);
    if (scwin.vBzProcsNo != "") {
        await scwin.fn_read_sync();
    }
    scwin.initForm();
};


